"""Join diagnostic scopes without double-counting setup/blocked methods."""
from pathlib import Path
import collections,hashlib,json,re
OUT=Path(__file__).resolve().parent
C=json.loads((OUT/'canonical-gate-comparison.json').read_text());M=json.loads((OUT/'mapping-integrity-comparison.json').read_text());B=json.loads((OUT/'baseline/failure-inventory.json').read_text());N=json.loads((OUT/'candidate-gate/failure-inventory.json').read_text())
def identity(text):
 if text.startswith('setUpClass ('):return 'setUpClass:'+text[len('setUpClass ('):-1]
 m=re.match(r'^\S+ \(([^)]+)\)$',text)
 return m.group(1) if m else text
cids={identity(x['test']) for x in C['cases']};mids={identity(x['test']) for x in M['cases']};assert len(cids)==len(C['cases']);assert len(mids)==len(M['cases'])
rows=[{'scope':scope,'identity':identity(v['test']),'test':v['test'],'kind':v['kind'],'classification':v['classification'],'explanation':v['explanation']} for scope,doc in [('canonical',C),('mapping_integrity',M)] for v in doc['cases']]
doc_b=json.loads((OUT/'baseline-documentary.json').read_text());doc_c=json.loads((OUT/'candidate-documentary.json').read_text());assert doc_b['return_code']==doc_c['return_code']==1 and doc_b['output']==doc_c['output']=='disconnected documentary update chain\n'
chain_cases=[identity(x['test']) for x in N['failures'] if 'disconnected documentary update chain' in x['raw_traceback']]
stages=json.loads((OUT/'canonical-stage-boundary.json').read_text());assert all(len(x['executed_gate_steps'])==2 for x in [B,N])
r={'status':'ALL OBSERVED DIAGNOSTICS ACCOUNTED FOR; GATES DID NOT PASS','baseline':'3376e1c74e846e40e6863ec8b1f1c255349aa2d3','canonical':{'baseline':C['baseline_failure_counts'],'candidate':C['candidate_failure_counts'],'classifications':C['classification_counts'],'tests_run':int(re.search(r'Ran (\d+) tests',N['canonical_result']['test_summary'][0]).group(1)),'skipped':int(re.search(r'skipped=(\d+)',N['canonical_result']['outcome_summary'][0]).group(1)),'return_code':N['canonical_result']['return_code']},'mapping_integrity':{'baseline':M['baseline'],'candidate':M['candidate'],'classifications':M['classification_counts']},'cross_scope_duplicate_test_identities':sorted(cids&mids),'candidate_diagnostic_records_across_two_scopes':len(rows),'distinct_normalized_identities':len(cids|mids),'candidate_test_method_diagnostics':sum(not x['identity'].startswith('setUpClass:') for x in rows),'candidate_setup_diagnostics':sum(x['identity'].startswith('setUpClass:') for x in rows),'blocked_methods_not_counted_as_additional_diagnostics':M['blocked_tests'],'standalone_documentary_check':{'baseline':doc_b,'candidate':doc_c,'baseline_identical':True,'canonical_cases_sharing_same_error_message':chain_cases,'counting_note':'A separate command failure, disclosed separately; it repeats a preexisting diagnostic cause and is not an additional unittest record in the two-scope count.'},'canonical_executed_stages':{'baseline':B['executed_gate_steps'],'candidate':N['executed_gate_steps']},'canonical_unreached_stages':stages,'newly_failing_cases_due_to_approved_data':M['new_failing_cases'],'demonstrated_unexplained_regressions':[],'normalization_and_cause_note':'Diagnostic records are not necessarily independent defects. Distinct test methods remain separate records even when they exercise the same stale fixture/hash/transition expectation. All raw differences remain in the two detailed comparisons.','cases':rows,'waiver':'No exception or release waiver is authorized or implied. make check was executed and did not pass; later canonical stages were not reached. Three newly failing strict-BFO fixtures were preserved unchanged because authorization extended only to the assessment-count correction.'}
(OUT/'exception-inventory.json').write_text(json.dumps(r,indent=2)+'\n')
print(json.dumps({k:r[k] for k in ['candidate_diagnostic_records_across_two_scopes','distinct_normalized_identities','cross_scope_duplicate_test_identities','candidate_test_method_diagnostics','candidate_setup_diagnostics','newly_failing_cases_due_to_approved_data','demonstrated_unexplained_regressions']},indent=2))
